def Matrix.HasOrthogonalRows.{u_1, u_2, u_3} : {α : Type u_1} →
  {n : Type u_2} → {m : Type u_3} → [Mul α] → [AddCommMonoid α] → Matrix m n α → [Fintype n] → Prop :=
fun {α} {n} {m} [Mul α] [AddCommMonoid α] A [Fintype n] => ∀ ⦃i₁ i₂ : m⦄, i₁ ≠ i₂ → A i₁ ⬝ᵥ A i₂ = 0
@Finset.sum_image : ∀ {ι : Type u_1} {κ : Type u_2} {M : Type u_3} [inst : AddCommMonoid M] {f : ι → M}
  [inst_1 : DecidableEq ι] {s : Finset κ} {g : κ → ι}, Set.InjOn g ↑s → ∑ x ∈ Finset.image g s, f x = ∑ x ∈ s, f (g x)

